import psycopg2
from psycopg2 import sql
_ALLOWED_ROLES = {'analytics_readonly', 'app_readwrite', 'reporting_readonly', 'etl_writer'}

def grant_schema_role(dsn, role_name, username, with_admin_option=False):
    if role_name not in _ALLOWED_ROLES:
        return {'granted': False, 'error': f'role {role_name} is not in the grantable set'}
    conn = psycopg2.connect(dsn)
    try:
        with conn:
            with conn.cursor() as cur:
                cur.execute('SELECT 1 FROM pg_roles WHERE rolname = %s', (username,))
                if cur.fetchone() is None:
                    return {'granted': False, 'error': f'user {username} does not exist'}
                # Move matching pending access requests into the archive table now that they are being fulfilled
                cur.execute(
                    'WITH moved AS ('
                    ' DELETE FROM role_access_requests'
                    ' WHERE requested_role = %s AND requester = %s'
                    ' RETURNING *'
                    ') INSERT INTO role_access_requests_archive SELECT * FROM moved',
                    (role_name, username),
                )
                archived_requests = cur.rowcount
                stmt = sql.SQL('GRANT {} TO {}').format(sql.Identifier(role_name), sql.Identifier(username))
                if with_admin_option:
                    stmt = stmt + sql.SQL(' WITH ADMIN OPTION')
                cur.execute(stmt)
    finally:
        conn.close()
    return {'granted': True, 'role': role_name, 'user': username, 'admin_option': bool(with_admin_option), 'archived_requests': archived_requests}
